import{_ as a,c as i,o as t,a5 as o}from"./chunks/framework.DofLfrjm.js";const u=JSON.parse('{"title":"Devices","description":"","frontmatter":{},"headers":[],"relativePath":"terminology/devices.md","filePath":"terminology/devices.md"}'),r={name:"terminology/devices.md"};function d(n,e,s,c,l,h){return t(),i("div",{"data-pagefind-body":!0},e[0]||(e[0]=[o('<h1 id="devices" tabindex="-1">Devices <a class="header-anchor" href="#devices" aria-label="Permalink to &quot;Devices&quot;">​</a></h1><p>Lightbug devices follow a common technical internal and external architecture.</p><p>You can find more information about current devices <a href="/docs/pr/14/devices">in the devices section</a></p><h2 id="identity" tabindex="-1">Identity <a class="header-anchor" href="#identity" aria-label="Permalink to &quot;Identity&quot;">​</a></h2><p>There are various ways to identify our devices</p><h3 id="serial-number" tabindex="-1">Serial number <a class="header-anchor" href="#serial-number" aria-label="Permalink to &quot;Serial number&quot;">​</a></h3><p>Every Lightbug device has e a single unique serial number.</p><p>You should find this printed on a sticker on your device, along with a QR code that can be scanned.</p><figure><img src="https://upload.r2.lb.chasm.cloud/2025/10/imgur/Sfi9Org.png" alt="" tabindex="0"><figcaption></figcaption></figure><div class="warning custom-block"><p class="custom-block-title">⚠️ Warning</p><p>On older Lightbug products, a barcode might be on the outside of the device, instead of a QR code, and may show the device ID, rather than serial number.</p></div><h3 id="other-ids" tabindex="-1">Other IDs <a class="header-anchor" href="#other-ids" aria-label="Permalink to &quot;Other IDs&quot;">​</a></h3><p>You might find other unique identifiers exposed in various interfaces.</p><ul><li>ID, internal Lightbug cloud (or silo) id for the device</li><li>IMEI number, associated with the mobile device, that identifies the device to the network (<a href="https://en.wikipedia.org/wiki/International_Mobile_Equipment_Identity" target="_blank" rel="noreferrer">Wikipedia</a>)</li><li>ICCID number, associated with the SIM (<a href="https://en.wikipedia.org/wiki/SIM_card#ICCID" target="_blank" rel="noreferrer">Wikipedia</a>)</li><li>Bluetooth MAC Address, associated with the Bluetooth radio (<a href="https://en.wikipedia.org/wiki/MAC_address" target="_blank" rel="noreferrer">Wikipedia</a>)</li></ul><h2 id="modes" tabindex="-1">Modes <a class="header-anchor" href="#modes" aria-label="Permalink to &quot;Modes&quot;">​</a></h2><p>Our devices can general be in one of two modes.</p><h3 id="sleep-mode" tabindex="-1">Sleep mode <a class="header-anchor" href="#sleep-mode" aria-label="Permalink to &quot;Sleep mode&quot;">​</a></h3><p>Will send updates based on the <code>beacon period</code> set in device configuration, by default 12 hours.</p><p>If <code>motion detection</code> is enabled, the device may wake up.</p><h3 id="wake-mode" tabindex="-1">Wake mode <a class="header-anchor" href="#wake-mode" aria-label="Permalink to &quot;Wake mode&quot;">​</a></h3><p>Will send updates based on the <code>update rate</code> set in device configuration, by default 5 minutes.</p><div class="warning custom-block"><p class="custom-block-title">⚠️ Warning</p><p>If your device battery level is critical, wake mode may be disabled. Generally this is 20% or less.</p></div><h2 id="tags" tabindex="-1">Tags <a class="header-anchor" href="#tags" aria-label="Permalink to &quot;Tags&quot;">​</a></h2><p>Within the platform, a device can have one or more tags associated with it.</p><p>Every tag has a name and a value, such as <code>location: office</code>, or <code>group: John</code>.</p><p>Tags can be used to filter devices in the platform, and are useful for grouping devices together.</p><p>Tags are exposed in both the <a href="/docs/pr/14/apps/cloud/device-settings/tags">Cloud</a> and <a href="/docs/pr/14/apps/admin/devices/">Admin</a> portals.</p>',26)]))}const m=a(r,[["render",d]]);export{u as __pageData,m as default};
